package share

import (
	"encoding/json"
	"fmt"
	"net/http"
)

func (h *Handler) serveBrowser(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	prefixJSON, _ := json.Marshal(h.prefix)
	nameJSON, _ := json.Marshal(h.name)
	_, _ = fmt.Fprintf(w, browserHTML, prefixJSON, nameJSON, len(h.passwordHash) > 0)
}

const browserHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoPort Share</title><style>
:root{color-scheme:light dark;font-family:Inter,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:#f1f7f5;color:#102124}main{max-width:980px;margin:auto;padding:28px 18px 60px}.brand{font-weight:800;font-size:20px;color:#159b6d}.hero{margin:28px 0 20px}.hero h1{font-size:clamp(28px,5vw,48px);margin:8px 0}.muted{color:#60706c}.bar,.card{background:#fff;border:1px solid #dce8e4;border-radius:18px;box-shadow:0 18px 50px -40px #173d32}.bar{display:flex;gap:12px;align-items:center;padding:14px 16px;margin-bottom:14px;overflow:auto}.bar button,.action{border:0;border-radius:10px;padding:10px 14px;background:#18302c;color:#fff;cursor:pointer;text-decoration:none;white-space:nowrap}.crumb{color:#177e5d;background:none!important;padding:4px!important}.card{overflow:hidden}.row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:14px;align-items:center;padding:14px 16px;border-bottom:1px solid #edf2f0}.row:last-child{border:0}.name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}.size{color:#72807c;font-size:13px}.empty,.error{padding:52px 20px;text-align:center}.modal{position:fixed;inset:0;background:#102124cc;display:flex;align-items:center;justify-content:center;padding:20px}.dialog{width:min(400px,100%%);background:#fff;color:#102124;border-radius:20px;padding:24px}.dialog input{width:100%%;padding:12px;border:1px solid #ccd9d5;border-radius:10px;margin:14px 0}.preview{position:fixed;inset:0;background:#07100fee;display:flex;flex-direction:column;padding:20px}.preview header{display:flex;justify-content:space-between;color:#fff}.preview iframe,.preview img{margin:auto;max-width:96%%;max-height:88%%;width:100%%;height:100%%;object-fit:contain;border:0;background:white}.hidden{display:none!important}@media(max-width:600px){.row{grid-template-columns:minmax(0,1fr) auto}.size{display:none}}@media(prefers-color-scheme:dark){body{background:#071012;color:#edf8f4}.card,.bar{background:#102124;border-color:#29423f}.muted,.size{color:#9aada7}.row{border-color:#203733}}
</style></head><body><main><div class="brand">GoPort Share</div><section class="hero"><p class="muted">Files stay on the sender's computer</p><h1 id="title"></h1><p class="muted">This folder is available only while the GoPort session remains connected.</p></section><div class="bar"><button onclick="up()">Up</button><div id="crumbs"></div><a id="zip" class="action">Download folder ZIP</a></div><section class="card" id="files"><div class="empty">Loading files…</div></section></main><div id="password" class="modal hidden"><form class="dialog" onsubmit="unlock(event)"><h2>Password required</h2><p class="muted">Enter the password provided by the sender.</p><input id="pw" type="password" autocomplete="current-password" required minlength="8"><button class="action">Unlock</button><p id="pwerr" class="error"></p></form></div><div id="preview" class="preview hidden"><header><strong id="previewName"></strong><button class="action" onclick="closePreview()">Close</button></header><div id="previewBody" style="display:contents"></div></div><script>
const base=%s,folder=%s,passwordRequired=%t;let current='.';const esc=encodeURIComponent;
function human(n){if(!n)return '0 B';const u=['B','KB','MB','GB','TB'],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),4);return (n/1024**i).toFixed(i?1:0)+' '+u[i]}
async function load(p='.'){current=p;const r=await fetch(base+'/api/list?path='+esc(p));if(r.status===401){document.querySelector('#password').classList.remove('hidden');return}if(!r.ok){files.innerHTML='<div class="error">This folder is unavailable.</div>';return}const d=await r.json();title.textContent=d.name;zip.href=base+'/zip?path='+esc(p);crumbs.replaceChildren();let acc='.';const root=document.createElement('button');root.className='crumb';root.textContent=d.name;root.onclick=()=>load('.');crumbs.append(root);if(p!=='.')for(const part of p.split('/')){acc=acc==='.'?part:acc+'/'+part;const b=document.createElement('button');b.className='crumb';b.textContent=' / '+part;const target=acc;b.onclick=()=>load(target);crumbs.append(b)}files.replaceChildren();if(!d.entries.length){files.innerHTML='<div class="empty">This folder is empty.</div>';return}for(const e of d.entries){const row=document.createElement('div');row.className='row';const name=document.createElement('button');name.className='crumb name';name.textContent=(e.directory?'📁 ':'📄 ')+e.name;name.onclick=()=>e.directory?load(e.path):(e.previewable?showPreview(e):location.assign(base+'/file?path='+esc(e.path)));const size=document.createElement('span');size.className='size';size.textContent=e.directory?'Folder':human(e.size);const a=document.createElement('a');a.className='action';a.textContent=e.directory?'Open':'Download';a.href=e.directory?'#':base+'/file?path='+esc(e.path);a.onclick=e.directory?(ev=>{ev.preventDefault();load(e.path)}):null;row.append(name,size,a);files.append(row)}}
function up(){if(current==='.')return;const p=current.split('/');p.pop();load(p.join('/')||'.')}
async function unlock(e){e.preventDefault();pwerr.textContent='';const r=await fetch(base+'/api/unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:pw.value})});if(!r.ok){pwerr.textContent='Invalid password.';return}password.classList.add('hidden');pw.value='';load(current)}
function showPreview(e){previewName.textContent=e.name;previewBody.replaceChildren();const src=base+'/file?preview=1&path='+esc(e.path),el=/\.(png|jpe?g|gif|webp)$/i.test(e.name)?document.createElement('img'):document.createElement('iframe');el.src=src;el.title=e.name;previewBody.append(el);preview.classList.remove('hidden')}
function closePreview(){preview.classList.add('hidden');previewBody.replaceChildren()}load();
</script></body></html>`
